const config = await fetch("app.json").then(x => x.json())
const key = `studio-${config.kind}-v1`
let state = JSON.parse(localStorage.getItem(key) || "{}")
const app = document.querySelector("#app")
document.title = config.name
document.documentElement.style.setProperty("--accent", config.accent)
document.documentElement.style.setProperty("--accent2", config.accent2)
const save = () => localStorage.setItem(key, JSON.stringify(state))
const esc = value => String(value ?? "").replace(/[&<>'"]/g, x => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"}[x]))
const frame = (content, action = "New") => `<div class="shell"><aside class="side"><div class="brand"><span class="mark">${esc(config.name[0])}</span><span>${esc(config.name)}</span></div><button class="new" id="new">+ ${action}</button><nav class="nav"><button class="active">Workspace</button><button id="library">Library</button><button id="settings">Settings</button></nav><small>Stored in this browser</small></aside><main>${content}</main></div>`
const header = (title = config.name, sub = config.tagline) => `<header class="top"><div><p class="eyebrow">${esc(config.name)}</p><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div><div class="button-row"><button class="ghost" id="export">Export</button></div></header>`

function renderCanvas() {
  app.innerHTML = frame(header("A thought, with room to move.", "Sketch freely, then save a clean browser-native board.") + `<section class="workspace"><div class="surface"><div class="surface-head"><span>Untitled canvas</span><button class="ghost" id="clear">Clear</button></div><div class="canvas-wrap"><canvas class="draw" id="draw"></canvas></div></div><aside class="surface card tools"><h3>Tools</h3><label class="field">Ink color <input type="color" id="color" value="${state.color || config.accent}"></label><label class="field">Stroke <input type="range" id="size" min="1" max="18" value="${state.size || 4}"></label><div class="item"><span>Draw directly on the board</span><span>✦</span></div></aside></section>`, "New board")
  const canvas = document.querySelector("#draw"), ctx = canvas.getContext("2d"), color = document.querySelector("#color"), size = document.querySelector("#size")
  const resize = () => { const image = canvas.toDataURL(); canvas.width = canvas.clientWidth * devicePixelRatio; canvas.height = canvas.clientHeight * devicePixelRatio; ctx.scale(devicePixelRatio, devicePixelRatio); if (state.image) { const i = new Image(); i.onload = () => ctx.drawImage(i, 0, 0, canvas.clientWidth, canvas.clientHeight); i.src = state.image } else if (image !== "data:,") { const i = new Image(); i.onload = () => ctx.drawImage(i, 0, 0, canvas.clientWidth, canvas.clientHeight); i.src = image } }
  resize(); let drawing = false
  const point = e => { const r = canvas.getBoundingClientRect(), p = e.touches?.[0] || e; return [p.clientX-r.left,p.clientY-r.top] }
  const draw = e => { if (!drawing) return; const [x,y]=point(e); ctx.lineTo(x,y); ctx.stroke(); state.image=canvas.toDataURL(); save() }
  canvas.onpointerdown = e => { drawing=true; ctx.beginPath(); const [x,y]=point(e); ctx.moveTo(x,y); ctx.lineCap="round"; ctx.strokeStyle=color.value; ctx.lineWidth=size.value; canvas.setPointerCapture(e.pointerId) }; canvas.onpointermove=draw; canvas.onpointerup=()=>drawing=false
  color.oninput=()=>{state.color=color.value;save()};size.oninput=()=>{state.size=size.value;save()}; document.querySelector("#clear").onclick=()=>{state.image="";save();ctx.clearRect(0,0,canvas.width,canvas.height)}
}
function renderPulse() {
  const logs = state.logs || []
  app.innerHTML = frame(header("Send one precise request.", "An API workspace that keeps your endpoints and responses in this browser.") + `<section class="workspace"><div class="surface card"><form id="request" class="tools"><label class="field">Method <select id="method"><option>GET</option><option>POST</option><option>PUT</option><option>DELETE</option></select></label><label class="field">Endpoint <input id="url" placeholder="https://api.example.com/data" value="${esc(state.url||"")}"></label><label class="field">JSON body <textarea id="body" placeholder='{"hello":"world"}'>${esc(state.body||"")}</textarea></label><button class="primary">Send request</button></form><pre id="response" class="empty">${esc(state.response || "Response will appear here.")}</pre></div><aside class="surface card"><h3>Recent requests</h3><div class="feed">${logs.map(x=>`<div class="item"><span>${esc(x.method)} ${esc(x.url)}</span></div>`).join("")||"<p class='empty'>Your request history stays local.</p>"}</div></aside></section>`, "New request")
  document.querySelector("#request").onsubmit=async e=>{e.preventDefault();const method=document.querySelector("#method").value,url=document.querySelector("#url").value,body=document.querySelector("#body").value;state={...state,url,body,response:"Sending…",logs:[{method,url},...logs].slice(0,12)};save();document.querySelector("#response").textContent="Sending…";try{const res=await fetch(url,{method,headers:{"content-type":"application/json"},body:["GET","DELETE"].includes(method)?undefined:body||undefined});state.response=`${res.status} ${res.statusText}\n\n${await res.text()}`}catch(err){state.response=`Request failed: ${err.message}\n\nSome APIs block browser requests with CORS.`}save();document.querySelector("#response").textContent=state.response}
}
function renderLedger() {
  const entries=state.entries||[],total=entries.reduce((s,x)=>s+Number(x.amount),0)
  app.innerHTML=frame(header("Money, quietly organized.","A local-first ledger for what came in, what went out, and what is next.")+`<section class="workspace"><div class="surface card"><div class="stat">${total.toLocaleString(undefined,{style:"currency",currency:"USD"})}</div><p class="sub">Current balance</p><form id="entry" class="tools" style="margin-top:22px"><label class="field">Description <input id="description" placeholder="Coffee, invoice, rent…"></label><label class="field">Amount <input id="amount" type="number" step="0.01" placeholder="Use - for spending"></label><button class="primary">Add transaction</button></form></div><aside class="surface card"><h3>Recent activity</h3><div class="feed">${entries.map((x,i)=>`<div class="item"><span>${esc(x.text)}</span><strong>${Number(x.amount).toLocaleString(undefined,{style:"currency",currency:"USD"})}</strong><button data-remove="${i}">×</button></div>`).join("")||"<p class='empty'>Add your first transaction.</p>"}</div></aside></section>`,"New transaction")
  document.querySelector("#entry").onsubmit=e=>{e.preventDefault();const text=document.querySelector("#description").value.trim(),amount=document.querySelector("#amount").value;if(!text||!amount)return;state.entries=[{text,amount},...entries];save();renderLedger()};document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{state.entries.splice(Number(b.dataset.remove),1);save();renderLedger()})
}
function renderSchema() {
  const tables=state.tables||[]
  app.innerHTML=frame(header("Make data legible.","Name tables, define fields, and keep a browser-first schema close at hand.")+`<section class="workspace"><div class="surface card"><form id="table" class="tools"><label class="field">Table name <input id="name" placeholder="customers"></label><label class="field">Fields, one per line <textarea id="fields" placeholder="id · uuid\nemail · text\ncreated_at · timestamp"></textarea></label><button class="primary">Add table</button></form></div><aside class="surface card"><h3>Schema</h3><div class="feed">${tables.map((t,i)=>`<div class="tile"><h3>${esc(t.name)} <button data-remove="${i}">×</button></h3><p>${esc(t.fields).replaceAll("\n","<br>")}</p></div>`).join("")||"<p class='empty'>Start with a table.</p>"}</div></aside></section>`,"New table")
  document.querySelector("#table").onsubmit=e=>{e.preventDefault();const name=document.querySelector("#name").value.trim(),fields=document.querySelector("#fields").value.trim();if(!name)return;state.tables=[{name,fields},...tables];save();renderSchema()};document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{state.tables.splice(Number(b.dataset.remove),1);save();renderSchema()})
}
function renderList(kind, title, helper, label) {
  const items=state.items||[];app.innerHTML=frame(header(title,helper)+`<section class="workspace"><div class="surface card"><form id="add" class="tools"><label class="field">${label}<input id="text" placeholder="Start with one clear item"></label><button class="primary">Add</button></form><div class="board" style="margin-top:22px">${items.map((x,i)=>`<div class="tile"><h3>${esc(x)}</h3><p>Saved locally</p><button data-remove="${i}">Remove</button></div>`).join("")||"<p class='empty'>Nothing here yet.</p>"}</div></div><aside class="surface card"><h3>Today</h3><div class="stat">${items.length}</div><p class="sub">${kind}</p></aside></section>`,"New")
  document.querySelector("#add").onsubmit=e=>{e.preventDefault();const text=document.querySelector("#text").value.trim();if(text){state.items=[text,...items];save();renderList(kind,title,helper,label)}};document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{state.items.splice(Number(b.dataset.remove),1);save();renderList(kind,title,helper,label)})
}
function renderGallery(){const photos=state.photos||[];app.innerHTML=frame(header("A quieter place for pictures.","Choose files from this device. Nothing leaves your browser.")+`<section class="workspace"><div class="surface card"><input id="upload" type="file" accept="image/*" multiple><div class="board" id="photos" style="margin-top:18px">${photos.map(x=>`<img class="tile" style="width:100%;height:150px;object-fit:cover;padding:0" src="${x}">`).join("")||"<p class='empty'>Add a few images to begin.</p>"}</div></div><aside class="surface card"><h3>Library</h3><div class="stat">${photos.length}</div><p class="sub">images this visit</p></aside></section>`,"Import")
  document.querySelector("#upload").onchange=e=>{Promise.all([...e.target.files].map(f=>new Promise(r=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.readAsDataURL(f)}))).then(items=>{state.photos=[...items,...photos].slice(0,18);save();renderGallery()})}
}
function renderGame(title,desc,kind){app.innerHTML=frame(header(title,desc)+`<section class="game"><div style="text-align:center"><p class="eyebrow" style="color:#d3d0cc">${kind}</p><h2 id="score">Ready?</h2><p class="sub" style="color:#d3d0cc;margin:12px auto 23px">Tap when the color changes. Your score is saved here.</p><button id="play">Play</button></div></section>`,"New run");document.querySelector("#play").onclick=()=>{const button=document.querySelector("#play"),score=document.querySelector("#score"),start=Date.now();button.textContent="Wait…";setTimeout(()=>{button.textContent="Tap now";button.style.background=config.accent;button.onclick=()=>{const result=Date.now()-start-900;state.best=Math.min(state.best||9999,result);save();score.textContent=`${result} ms · Best ${state.best} ms`;button.textContent="Play again";button.style.background="white";button.onclick=()=>renderGame(title,desc,kind)}},900+Math.random()*1800)} }
function renderBlocksmith(){renderList("blocks","Build the idea before the syntax.","Arrange simple instructions and keep the draft in this browser.","Instruction")}
function renderLoopline(){renderList("connections","See how the pieces affect each other.","Capture a system one connection at a time.","Connection")}
function renderMarket(){renderList("journal entries","Trade the process, not the noise.","Keep a focused local journal of setups, decisions, and outcomes.","Journal entry")}
function exportData(){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.download=`${config.name.toLowerCase().replaceAll(" ","-")}.json`;a.click()}
function render(){if(config.kind==="canvas")renderCanvas();else if(config.kind==="pulse")renderPulse();else if(config.kind==="ledger")renderLedger();else if(config.kind==="schema")renderSchema();else if(config.kind==="loop")renderLoopline();else if(config.kind==="blocks")renderBlocksmith();else if(config.kind==="market")renderMarket();else if(config.kind==="gallery")renderGallery();else renderGame(config.name,config.tagline,config.kind);document.querySelector("#export").onclick=exportData;document.querySelector("#new").onclick=()=>{state={};save();render()};document.querySelector("#library").onclick=()=>alert("Everything in this app is stored locally in your browser.");document.querySelector("#settings").onclick=()=>alert("No account, telemetry, or API key is required for the local version.")}
render()
